{project_card(3,'Research Advisor Matching','Institutionally deployed','An explainable allocation workflow that combines expertise fit with advisor capacity and keeps the recommendation open to human review.','Creator and developer: matching logic, workload balancing, recommendation explanations and a browser-local assignment trail.','advisor-matching','https://github.com/gurkancamok/evidence-based-advisor-matching')}
